RUNTIME_C = ["gwnum.c", "gweval.c", "gwio.c", "gwfile.c",
             "gwscreen.c", "gwsys.c", "gwstmt.c", "gwgui.c", "gwtext.c"]

MSVC = (r"C:\Program Files (x86)\Microsoft Visual Studio\18\BuildTools"
        r"\VC\Tools\MSVC\14.51.36231")
SDK = r"C:\Program Files (x86)\Windows Kits\10"
SDK_VER = "10.0.26100.0"


def cl_path():
    return os.path.join(MSVC, "Bin", "Hostx64", "x64", "cl.exe")


def build_env(workdir):
    inc = [
        os.path.join(MSVC, "Include"),
        os.path.join(MSVC, "Include", "shared"),
        os.path.join(MSVC, "Include", "ucrt"),
        os.path.join(SDK, "Include", SDK_VER, "ucrt"),
        os.path.join(SDK, "Include", SDK_VER, "um"),
        os.path.join(SDK, "Include", SDK_VER, "shared"),
    ]
    lib = [
        os.path.join(MSVC, "Lib", "x64"),
        os.path.join(MSVC, "Lib", "ucrt", "x64"),
        os.path.join(SDK, "Lib", SDK_VER, "ucrt", "x64"),
        os.path.join(SDK, "Lib", SDK_VER, "um", "x64"),
    ]
    env = dict(os.environ)
    env["INCLUDE"] = ";".join(inc)
    env["LIB"] = ";".join(lib)
    env["PATH"] = os.path.join(MSVC, "Bin", "Hostx64", "x64") + os.pathsep + env.get("PATH", "")
    env["TMP"] = workdir
    env["TEMP"] = workdir
    return env


def stem_of(path):
    return os.path.splitext(os.path.basename(path))[0]


def build_one(genc, workdir, bas, env, keep_c=False, c_only=False,
              native=False):
    """One .bas -> .exe.  Returns True on success.

    keep_c: copy the generated <name>.c next to the source before the temp
            workdir is deleted, so the C tables can be inspected.
    c_only: stop after generating the .c (no cl compile/link step).
    """
    bas = os.path.abspath(bas)
    # A bare name (no .bas) defaults to <name>.bas.
    if not bas.lower().endswith(".bas"):
        candidate = bas + ".bas"
        if os.path.exists(candidate):
            bas = candidate
    if not os.path.exists(bas):
        print("gwcbasic: file not found: %s" % bas)
        return False
    name = stem_of(bas)
    src_dir = os.path.dirname(bas)
    out_exe = os.path.join(src_dir, name + ".exe")
    out_c = os.path.join(workdir, name + ".c")
    try:
        if native:
            import nenc
            nenc.generate(bas, out_c)
        else:
            genc.generate(bas, out_c)
    except SystemExit as e:
        if str(e.code):
            print("gwcbasic: %s" % e.code)
        return False
    if keep_c or c_only:
        out_c_saved = os.path.join(src_dir, name + ".c")
        shutil.copyfile(out_c, out_c_saved)
        print("gwcbasic: %s -> %s (%d bytes)" %
              (name + ".bas", out_c_saved, os.path.getsize(out_c_saved)))
    if c_only:
        return True
    if os.path.exists(out_exe):
        os.remove(out_exe)
    srcs = [out_c] + [os.path.join(workdir, f) for f in RUNTIME_C]
    if native:
        srcs.append(os.path.join(workdir, "gwgen.c"))
    # Always /SUBSYSTEM:CONSOLE: a launched program starts WITH a console
    # (Explorer allocates one on a double-click; CRUN passes
    # CREATE_NEW_CONSOLE), so pre-window output has somewhere to go.
    # The runtime detaches the console at first window creation
    # (FreeConsole in gwgui.c create_window) -- the console window closes
    # at the moment the window opens; a program that never opens a window
    # keeps its console until it exits.  Manual launch and CRUN behave
    # identically.
    cmd = [cl_path(), "/nologo", "/O2", "/MT", "/GL", "/I:" + workdir] + srcs + [
        "/Fo:" + workdir + os.sep,
        "/Fe:" + out_exe,
        "/link", "/STACK:1000000000", "/LTCG", "/SUBSYSTEM:CONSOLE",
        "user32.lib", "gdi32.lib", "winmm.lib",
    ]
    r = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, env=env)
    if r.returncode != 0:
        print("gwcbasic: COMPILE-FAIL %s" % name)
        tail = (r.stderr or r.stdout).strip()
        for line in tail.splitlines()[-15:]:
            print("    " + line)
        return False
    print("gwcbasic: %s -> %s (%d bytes)"
          % (name + ".bas", os.path.relpath(out_exe), os.path.getsize(out_exe)))
    return True


def main(argv):
    if not argv or argv[0] in ("-h", "--help"):
        print(__doc__.strip())
        return 0 if argv else 2
    cl = cl_path()
    if not os.path.exists(cl):
        print("gwcbasic: cl.exe not found at %s" % cl)
        return 2
    # Parse the optional flags (may appear anywhere in argv); everything
    # else is a .bas path.  NATIVE is the default; --vm selects the legacy
    # VM codegen (diagnostic fallback / VM-side parity gate).
    keep_c = "--keep-c" in argv
    c_only = "--c-only" in argv
    native = "--vm" not in argv  # --native kept as a no-op alias
    bas_files = [a for a in argv
                 if a not in ("--keep-c", "--c-only", "--native", "--vm")]
    workdir = tempfile.mkdtemp(prefix="gwcbasic_")
    try:
        for fname, b64 in EMBEDDED.items():
            with open(os.path.join(workdir, fname), "wb") as f:
                f.write(base64.b64decode(b64))
        sys.path.insert(0, workdir)
        import genc
        env = build_env(workdir)
        ok = 0
        for bas in bas_files:
            if build_one(genc, workdir, bas, env, keep_c=keep_c,
                         c_only=c_only, native=native):
                ok += 1
        print("%d/%d %s" % (ok, len(bas_files),
                             "generated" if c_only else "built"))
        return 0 if ok == len(bas_files) else 1
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
